11	pub fn generate_assembly(program: &Program, output_file: &mut std::fs::File) -> Result<(), String> {
12	    let codes = program.build(program)?;
13	    for code in codes {
14	        writeln!(output_file, "{}", code).expect("Write error. ");
15	    }
16	    Ok(())
17	}
