19	const REGISTER_NAMES: [&str; 32] = [
20	    "zero", "ra", "sp", "gp", "tp", "t0", "t1", "t2", "fp", "s1", "a0", "a1", "a2", "a3", "a4",
21	    "a5", "a6", "a7", "s2", "s3", "s4", "s5", "s6", "s7", "s8", "s9", "s10", "s11", "t3", "t4",
22	    "t5", "x31",
23	];
24	
25	// const REGISTER_FOR_TEMP: [usize; 7] = [5, 6, 7, 28, 29, 30, 31];
26	const REGISTER_FOR_TEMP: [usize; 6] = [5, 6, 7, 28, 29, 30];
27	// const REGISTER_FOR_TEMP: [usize; 2] = [5, 6];
28	
29	const REGISTER_FOR_ARGS: [usize; 8] = [10, 11, 12, 13, 14, 15, 16, 17];
30	
31	const ARG_SIZE: usize = 4;
32	
33	const REG_A0: usize = 10;
34	const REG_SP: usize = 2;
35	const REG_RA: usize = 1;
36	/// This register is for temporary integers only!
37	const REG_X31: usize = 31;
38	/// This register is the second scratch register. It is only used when the
39	/// first scratch register (x31) holds a value that must be preserved.
40	const REG_GP: usize = 3;
41	
42	const MAX_SHORT_INT: isize = 2047;
43	const MIN_SHORT_INT: isize = -2048;
44	
45	pub struct MyBBValueTable<'a> {
46	    program: &'a Program,
47	    fd: &'a FunctionData,
48	    curr_time: i32,
49	    register_user: [Option<Value>; 32],
50	    register_used_time: [i32; 32], // LRU registers
51	    local_value_location: HashMap<Value, usize>,
52	}
53	
54	impl MyBBValueTable<'_> {
55	    fn new<'a>(program: &'a Program, fd: &'a FunctionData) -> MyBBValueTable<'a> {
56	        MyBBValueTable {
57	            program,
58	            fd,
59	            curr_time: 0,
60	            register_user: [None; 32],
61	            register_used_time: [0; 32],
62	            local_value_location: HashMap::new(),
63	        }
64	    }
65	
66	    fn __update_user(&mut self, reg: usize, user: Value) {
67	        self.curr_time += 1;
68	        self.register_user[reg] = Some(user);
69	        self.register_used_time[reg] = self.curr_time;
70	    }
71	    fn __free_user(&mut self, reg: usize) {
72	        self.register_user[reg] = None;
73	        self.register_used_time[reg] = 0;
74	    }
75	
76	    fn __is_value_in_register(&self, value: Value) -> Option<usize> {
77	        for i in 0..REGISTER_NAMES.len() {
78	            match self.register_user[i] {
79	                Some(v) => {
80	                    if v == value {
81	                        return Some(i);
82	                    }
83	                }
84	                None => {}
85	            }
86	        }
87	        None
88	    }
89	
90	    fn is_temp_value(&self, value: Value) -> bool {
91	        let value_data = match value.is_global() {
92	            true => self.program.borrow_value(value).clone(),
93	            false => self.fd.dfg().value(value).clone(),
94	        };
95	        match value_data.name() {
96	            Some(name) => name.starts_with("%"),
97	            None => true,
98	        }
99	    }
100	
101	    fn remove_temp_value(&mut self, value: Value) {
102	        // assert!(
103	        //     self.is_temp_value(value),
104	        //     "Can only remove temp values in table!"
105	        // );
106	        if !self.is_temp_value(value) {
107	            return;
108	        }
109	        if let Some(reg) = self.__is_value_in_register(value) {
110	            self.__free_user(reg);
111	        }
112	        self.local_value_location.remove(&value);
113	    }
114	
115	    /// Stores the register to `offset(sp)`. Handles both short (12-bit) and
116	    /// long immediate offsets.
117	    fn store_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
118	        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
119	            vec![format!("  sw\t{}, {}(sp)", REGISTER_NAMES[reg], offset)]
120	        } else {
121	            vec![
122	                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
123	                format!(
124	                    "  add\t{}, sp, {}",
125	                    REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_X31]
126	                ),
127	                format!("  sw\t{}, 0({})", REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]),
128	            ]
129	        }
130	    }
131	    /// Loads `offset(sp)` into the register. Handles both short (12-bit) and
132	    /// long immediate offsets.
133	    fn load_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
134	        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
135	            vec![format!("  lw\t{}, {}(sp)", REGISTER_NAMES[reg], offset)]
136	        } else {
137	            vec![
138	                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
139	                format!(
140	                    "  add\t{}, sp, {}",
141	                    REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_X31]
142	                ),
143	                format!("  lw\t{}, 0({})", REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]),
144	            ]
145	        }
146	    }
147	    /// Computes `sp + offset` into the register. Handles both short (12-bit)
148	    /// and long immediate offsets.
149	    fn add_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
150	        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
151	            vec![format!("  addi\t{}, sp, {}", REGISTER_NAMES[reg], offset)]
152	        } else {
153	            vec![
154	                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
155	                format!(
156	                    "  add\t{}, sp, {}",
157	                    REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
158	                ),
159	            ]
160	        }
161	    }
162	    fn load_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
163	        vec![format!(
164	            "  la\t{}, {}\n  lw\t{}, 0({})",
165	            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
166	        )]
167	    }
168	    fn store_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
169	        vec![format!(
170	            "  la\t{}, {}\n  sw\t{}, 0({})",
171	            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
172	        )]
173	    }
174	
175	    /// Writes back (and frees) every register that currently holds a global
176	    /// variable. Used at basic block boundaries.
177	    fn store_global_variables(&mut self) -> Vec<String> {
178	        let mut codes = vec![];
179	        for reg in 0..REGISTER_NAMES.len() {
180	            if let Some(value) = self.register_user[reg] {
181	                if value.is_global() {
182	                    codes.extend(self.save_register(reg));
183	                }
184	            }
185	        }
186	        codes
187	    }
188	
189	    /// Writes back (and frees) every register that currently holds a local
190	    /// value (named variables, temporaries, arguments). Used at basic block
191	    /// boundaries.
192	    fn store_local_variables(&mut self) -> Vec<String> {
193	        let mut codes = vec![];
194	        for reg in 0..REGISTER_NAMES.len() {
195	            if let Some(value) = self.register_user[reg] {
196	                if !value.is_global() {
197	                    codes.extend(self.save_register(reg));
198	                }
199	            }
200	        }
201	        codes
202	    }
203	
204	    /// Kick the value in a register and store it to memory.
205	    fn save_register(&mut self, reg: usize) -> Vec<String> {
206	        let user = match self.register_user[reg] {
207	            Some(user) => user,
208	            None => return vec![],
209	        };
210	        let mut codes = vec![];
211	        if user.is_global() {
212	            let value_data = self.program.borrow_value(user).clone();
213	            if let koopa::ir::ValueKind::GlobalAlloc(_) = value_data.kind() {
214	                let name = value_data.name().unwrap()[1..].to_string();
215	                codes.extend(self.store_global(reg, name));
216	            }
217	            // Global constants are never modified, so there is no need to save them.
218	        } else {
219	            let value_data = self.fd.dfg().value(user).clone();
220	            match value_data.kind() {
221	                // Constants do not have a memory location.
222	                koopa::ir::ValueKind::Integer(_)
223	                | koopa::ir::ValueKind::ZeroInit(_)
224	                | koopa::ir::ValueKind::Undef(_) => {}
225	                _ => {
226	                    if let Some(offset) = self.local_value_location.get(&user) {
227	                        codes.extend(self.store_with_offset(reg, *offset as isize));
228	                    }
229	                }
230	            }
231	        }
232	        self.__free_user(reg);
233	        codes
234	    }
235	
236	    /// Finds a usable register.
237	    /// If all registers are being used, then kicks one.
238	    fn get_tmp_reg(&mut self) -> (usize, Vec<String>) {
239	        // Prefer a free register.
240	        for &reg in REGISTER_FOR_TEMP.iter() {
241	            if self.register_user[reg].is_none() {
242	                return (reg, vec![]);
243	            }
244	        }
245	        // Otherwise, kick the least recently used register.
246	        let mut lru_reg = REGISTER_FOR_TEMP[0];
247	        for &reg in REGISTER_FOR_TEMP.iter() {
248	            if self.register_used_time[reg] < self.register_used_time[lru_reg] {
249	                lru_reg = reg;
250	            }
251	        }
252	        let codes = self.save_register(lru_reg);
253	        (lru_reg, codes)
254	    }
255	
256	    /// Want to visit a value. Make it appear in a register.
257	    fn want_to_visit_value(
258	        &mut self,
259	        value: Value,
260	        do_load: bool,
261	        use_certain_reg: Option<usize>,
262	    ) -> (usize, Vec<String>) {
263	        let mut codes = vec![];
264	        // The value is already in a register.
265	        if let Some(reg) = self.__is_value_in_register(value) {
266	            match use_certain_reg {
267	                Some(target) if target != reg => {
268	                    // Move the value to the target register.
269	                    codes.extend(self.save_register(target));
270	                    codes.push(format!(
271	                        "  mv\t{}, {}",
272	                        REGISTER_NAMES[target], REGISTER_NAMES[reg]
273	                    ));
274	                    self.__free_user(reg);
275	                    self.__update_user(target, value);
276	                    return (target, codes);
277	                }
278	                _ => {
279	                    self.__update_user(reg, value);
280	                    return (reg, codes);
281	                }
282	            }
283	        }
284	        // Choose a register.
285	        let reg = match use_certain_reg {
286	            Some(target) => {
287	                codes.extend(self.save_register(target));
288	                target
289	            }
290	            None => {
291	                let (reg, save_codes) = self.get_tmp_reg();
292	                codes.extend(save_codes);
293	                reg
294	            }
295	        };
296	        // Load the value into the register.
297	        if do_load {
298	            if value.is_global() {
299	                let value_data = self.program.borrow_value(value).clone();
300	                match value_data.kind() {
301	                    koopa::ir::ValueKind::Integer(int) => {
302	                        codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], int.value()))
303	                    }
304	                    koopa::ir::ValueKind::GlobalAlloc(_) => {
305	                        let name = value_data.name().unwrap()[1..].to_string();
306	                        codes.extend(self.load_global(reg, name));
307	                    }
308	                    _ => {}
309	                }
310	            } else {
311	                let value_data = self.fd.dfg().value(value).clone();
312	                match value_data.kind() {
313	                    koopa::ir::ValueKind::Integer(int) => {
314	                        codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], int.value()))
315	                    }
316	                    _ => {
317	                        if let Some(offset) = self.local_value_location.get(&value) {
318	                            codes.extend(self.load_with_offset(reg, *offset as isize));
319	                        }
320	                    }
321	                }
322	            }
323	        }
324	        self.__update_user(reg, value);
325	        (reg, codes)
326	    }
327	
328	    /// Assigns the value of `v1` to `v2`. `v2` should be a global variable or
329	    /// a local variable with a stack location.
330	    fn assign_v1_to_v2(&mut self, v1: Value, v2: Value) -> Vec<String> {
331	        let (reg1, mut codes) = self.want_to_visit_value(v1, true, None);
332	        if v2.is_global() {
333	            let value_data = self.program.borrow_value(v2).clone();
334	            let name = value_data.name().unwrap()[1..].to_string();
335	            codes.extend(self.store_global(reg1, name));
336	        } else {
337	            let offset = *self
338	                .local_value_location
339	                .get(&v2)
340	                .expect("assign_v1_to_v2: v2 has no stack location!");
341	            codes.extend(self.store_with_offset(reg1, offset as isize));
342	        }
343	        codes
344	    }
345	
346	    /// Example:
347	    /// getelemptr @a, 114 -> The absolute location of @a in memory.
348	    /// getelemptr %0, 514 -> The value of %0 (which is an address).
349	    fn get_absolute_location(&mut self, value: Value) -> (usize, Vec<String>) {
350	        if value.is_global() {
351	            let value_data = self.program.borrow_value(value).clone();
352	            let name = value_data.name().unwrap()[1..].to_string();
353	            let (reg, mut codes) = self.get_tmp_reg();
354	            codes.push(format!("  la\t{}, {}", REGISTER_NAMES[reg], name));
355	            (reg, codes)
356	        } else {
357	            let value_data = self.fd.dfg().value(value).clone();
358	            match value_data.kind() {
359	                koopa::ir::ValueKind::Alloc(_) => {
360	                    let offset = *self
361	                        .local_value_location
362	                        .get(&value)
363	                        .expect("get_absolute_location: alloc has no stack location!");
364	                    let (reg, mut codes) = self.get_tmp_reg();
365	                    codes.extend(self.add_with_offset(reg, offset as isize));
366	                    (reg, codes)
367	                }
368	                // The value itself is an address.
369	                _ => self.want_to_visit_value(value, true, None),
370	            }
371	        }
372	    }
373	}

