35	#[derive(Debug)]
36	pub struct MyIRGeneratorInfo {
37	    curr_block: Option<BasicBlock>,            // Current block
38	    break_tgt_blocks: Vec<BasicBlock>,         // Target blocks of break statements
39	    continue_tgt_blocks: Vec<BasicBlock>,      // Target blocks of continue statements
40	    curr_func: Option<Function>,               // Current function
41	    symbol_tables: SymbolTableStack,           // Symbol table: ident-(type, Value)
42	    bb_cnt: usize,                             // Number of BasicBlocks
43	    symbol_cnt: usize,                         // Number of named local symbols (for unique naming)
44	    function_table: HashMap<String, Function>, // Function table
45	}
46	
47	impl MyIRGeneratorInfo {
48	    fn check_duplicate_global_symbol(&self, name: &String) -> bool {
49	        let result_var = match self.symbol_tables.symbol_tables[0].get(name) {
50	            Some(s) => match s {
51	                SymbolTableEntry::Variable(_, _) => true,
52	                SymbolTableEntry::Constant(_, _) => false,
53	            },
54	            None => false,
55	        };
56	        let result_func = self.function_table.get(name).is_some();
57	        result_var || result_func
58	    }
59	}
