62	pub struct SymbolTableStack {
63	    symbol_tables: Vec<HashMap<String, SymbolTableEntry>>, // Symbol table: ident-(type, Value)
64	}
65	
66	impl SymbolTableStack {
67	    fn get(&self, name: &String) -> Option<&SymbolTableEntry> {
68	        for table in self.symbol_tables.iter().rev() {
69	            if let Some(symbol) = table.get(name) {
70	                return Some(symbol);
71	            }
72	        }
73	        None
74	    }
75	    // fn get_nearest(&self, name: &String) -> Option<&SymbolTableEntry> {
76	
77	    // }
78	    fn insert(&mut self, name: String, entry: SymbolTableEntry) {
79	        let table = self.symbol_tables.last_mut().unwrap();
80	        table.insert(name, entry);
81	    }
82	    fn add_new_table(&mut self) {
83	        self.symbol_tables.push(HashMap::new());
84	    }
85	    fn delete_new_table(&mut self) {
86	        self.symbol_tables.pop();
87	    }
88	    // fn curr_depth(&self) -> usize {
89	    //     self.symbol_tables.len() - 1
90	    // }
91	}
