429	    fn build(
430	        &self,
431	        program: &mut Program,
432	        my_ir_generator_info: &mut MyIRGeneratorInfo,
433	    ) -> Result<IRExpBuildResult, String> {
434	        match self {
435	            PrimaryExp::BracedExp(exp) => exp.build(program, my_ir_generator_info),
436	            PrimaryExp::Number(number) => number.build(program, my_ir_generator_info),
437	            PrimaryExp::LVal(lval) => match lval.build(program, my_ir_generator_info)? {
438	                IRLValBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int)),
439	                IRLValBuildResult::TempVal(value) => Ok(IRExpBuildResult::Value(value)),
440	                IRLValBuildResult::Addr(ptr) => {
441	                    let pointee_ty = match get_valuedata(ptr, program, my_ir_generator_info).ty().kind() {
442	                        TypeKind::Pointer(base) => base.clone(),
443	                        _ => return Err("LVal address is not a pointer!".to_string()),
444	                    };
445	                    if pointee_ty.is_i32() {
446	                        // Scalar: load the value.
447	                        let load = create_new_local_value(program, my_ir_generator_info).load(ptr);
448	                        insert_local_instructions(program, my_ir_generator_info, [load]);
449	                        Ok(IRExpBuildResult::Value(load))
450	                    } else {
451	                        // Array used as a value: decay to the pointer of its first element.
452	                        let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
453	                        let decayed =
454	                            create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, zero);
455	                        insert_local_instructions(program, my_ir_generator_info, [decayed]);
456	                        Ok(IRExpBuildResult::Value(decayed))
457	                    }
458	                }
459	            },
460	        }
461	    }
462	}
