515	/// This is a LVal Value. It should always be a local Value.
516	fn get_element_in_ndarray(
517	    array_or_pointer: Value,
518	    indexes: &[Value],
519	    program: &mut Program,
520	    my_ir_generator_info: &mut MyIRGeneratorInfo,
521	) -> IRLValBuildResult {
522	    let mut cur = array_or_pointer;
523	    for index in indexes {
524	        let cur_ty = get_valuedata(cur, program, my_ir_generator_info).ty().clone();
525	        let is_pointer_value = match cur_ty.kind() {
526	            TypeKind::Pointer(base) => matches!(base.kind(), TypeKind::Pointer(_)),
527	            _ => false,
528	        };
529	        if is_pointer_value {
530	            // The symbol is a pointer (array parameter): load the pointer
531	            // first, then advance it with `getptr`.
532	            let loaded = create_new_local_value(program, my_ir_generator_info).load(cur);
533	            let advanced =
534	                create_new_local_value(program, my_ir_generator_info).get_ptr(loaded, *index);
535	            insert_local_instructions(program, my_ir_generator_info, [loaded, advanced]);
536	            cur = advanced;
537	        } else {
538	            // The symbol is an array: get the element pointer directly.
539	            let element_ptr =
540	                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(cur, *index);
541	            insert_local_instructions(program, my_ir_generator_info, [element_ptr]);
542	            cur = element_ptr;
543	        }
544	    }
545	    // A pointer symbol with no index applied evaluates to the pointer itself.
546	    let cur_ty = get_valuedata(cur, program, my_ir_generator_info).ty().clone();
547	    if let TypeKind::Pointer(base) = cur_ty.kind() {
548	        if matches!(base.kind(), TypeKind::Pointer(_)) {
549	            let loaded = create_new_local_value(program, my_ir_generator_info).load(cur);
550	            insert_local_instructions(program, my_ir_generator_info, [loaded]);
551	            return IRLValBuildResult::TempVal(loaded);
552	        }
553	    }
554	    IRLValBuildResult::Addr(cur)
555	}

