261	/// Emits store instructions that store the flattened scalar slots into the
262	/// corresponding locations of the allocated memory.
263	fn emit_scalar_stores(
264	    shape: &[usize],
265	    scalars: &[Option<IRInitValBuildResult>],
266	    ptr: Value,
267	    program: &mut Program,
268	    my_ir_generator_info: &mut MyIRGeneratorInfo,
269	) -> Result<(), String> {
270	    if shape.len() == 1 {
271	        for (i, scalar) in scalars.iter().enumerate() {
272	            let index = create_new_local_value(program, my_ir_generator_info).integer(i as i32);
273	            let elem_ptr =
274	                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, index);
275	            insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
276	            let value = match scalar {
277	                Some(IRInitValBuildResult::Const(int)) => {
278	                    create_new_local_value(program, my_ir_generator_info).integer(*int)
279	                }
280	                Some(IRInitValBuildResult::Var(value)) => *value,
281	                Some(IRInitValBuildResult::Aggregate(_)) => {
282	                    unreachable!("Aggregate in scalar slot!")
283	                }
284	                None => create_new_local_value(program, my_ir_generator_info).integer(0),
285	            };
286	            let store = create_new_local_value(program, my_ir_generator_info).store(value, elem_ptr);
287	            insert_local_instructions(program, my_ir_generator_info, [store]);
288	        }
289	        Ok(())
290	    } else {
291	        let sub_size: usize = shape[1..].iter().product();
292	        for (i, chunk) in scalars.chunks(sub_size).enumerate() {
293	            let index = create_new_local_value(program, my_ir_generator_info).integer(i as i32);
294	            let elem_ptr =
295	                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(ptr, index);
296	            insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
297	            emit_scalar_stores(&shape[1..], chunk, elem_ptr, program, my_ir_generator_info)?;
298	        }
299	        Ok(())
300	    }
301	}
302	
303	/// Builds a new aggregate value from the initializer.
304	/// Returns the aggregate value and the total number of scalar slots.
305	fn build_new_aggregate(
306	    shape: &[usize],
307	    childs: &[Box<InitVal>],
308	    is_global: bool,
309	    program: &mut Program,
310	    my_ir_generator_info: &mut MyIRGeneratorInfo,
311	) -> Result<(Value, usize), String> {
312	    let total_size: usize = shape.iter().product();
313	    let mut scalars: Vec<Option<IRInitValBuildResult>> = std::iter::repeat_with(|| None)
314	        .take(total_size)
315	        .collect();
316	    flatten_initval(
317	        shape,
