329	/// Generates store instructions that store every element of an aggregate
330	/// value into the corresponding location of the allocated memory.
331	fn aggregate_to_store_insts(
332	    aggr: Value,
333	    aggr_ptr: Value,
334	    program: &mut Program,
335	    my_ir_generator_info: &mut MyIRGeneratorInfo,
336	) -> Result<(), String> {
337	    let aggr_data = get_valuedata(aggr, program, my_ir_generator_info);
338	    match aggr_data.kind() {
339	        koopa::ir::ValueKind::Aggregate(aggregate) => {
340	            let elems = aggregate.elems().clone();
341	            for (i, elem) in elems.iter().enumerate() {
342	                let index =
343	                    create_new_local_value(program, my_ir_generator_info).integer(i as i32);
344	                let elem_ptr = create_new_local_value(program, my_ir_generator_info)
345	                    .get_elem_ptr(aggr_ptr, index);
346	                insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
347	                let elem_data = get_valuedata(*elem, program, my_ir_generator_info);
348	                match elem_data.kind() {
349	                    koopa::ir::ValueKind::Aggregate(_) => {
350	                        aggregate_to_store_insts(*elem, elem_ptr, program, my_ir_generator_info)?;
351	                    }
352	                    _ => {
353	                        let store = create_new_local_value(program, my_ir_generator_info)
354	                            .store(*elem, elem_ptr);
355	                        insert_local_instructions(program, my_ir_generator_info, [store]);
356	                    }
357	                }
358	            }
359	            Ok(())
360	        }
361	        _ => {
362	            let store = create_new_local_value(program, my_ir_generator_info).store(aggr, aggr_ptr);
363	            insert_local_instructions(program, my_ir_generator_info, [store]);
364	            Ok(())
365	        }
366	    }
367	}
