379	                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
380	                IRExpBuildResult::Value(value) => {
381	                    if is_global {
382	                        Err(format!(
383	                            "Non-constant expression '{:?}' in global variable initval: {:?}",
384	                            exp, self

200	                )?;
