208	/// Returns the Koopa type of an array with the given shape.
209	#[allow(dead_code)]
210	fn type_of_shape(shape: &[usize]) -> Type {
211	    if shape.len() == 1 {
212	        Type::get_array(Type::get_i32(), shape[0])
