218	/// Builds a Koopa aggregate value from the flattened scalar slots.
219	/// All the scalar slots must be constant (or zero-initialized).
220	fn scalars_to_aggregate_value(
221	    shape: &[usize],
222	    scalars: &[Option<IRInitValBuildResult>],
223	    is_global: bool,
224	    program: &mut Program,
225	    my_ir_generator_info: &mut MyIRGeneratorInfo,
226	) -> Value {
227	    let new_integer = |int: i32, program: &mut Program, info: &mut MyIRGeneratorInfo| match is_global
228	    {
229	        true => program.new_value().integer(int),
230	        false => create_new_local_value(program, info).integer(int),
231	    };
232	    let elems: Vec<Value> = if shape.len() == 1 {
233	        scalars
234	            .iter()
235	            .map(|scalar| match scalar {
236	                Some(IRInitValBuildResult::Const(int)) => {
237	                    new_integer(*int, program, my_ir_generator_info)
238	                }
239	                Some(IRInitValBuildResult::Var(value)) => *value,
240	                Some(IRInitValBuildResult::Aggregate(_)) => {
241	                    unreachable!("Aggregate in scalar slot!")
242	                }
243	                None => new_integer(0, program, my_ir_generator_info),
244	            })
245	            .collect()
246	    } else {
247	        let sub_size: usize = shape[1..].iter().product();
248	        scalars
249	            .chunks(sub_size)
250	            .map(|chunk| {
251	                scalars_to_aggregate_value(&shape[1..], chunk, is_global, program, my_ir_generator_info)
252	            })
253	            .collect()
254	    };
255	    match is_global {
256	        true => program.new_value().aggregate(elems),
257	        false => create_new_local_value(program, my_ir_generator_info).aggregate(elems),
258	    }
259	}

