//! Convert a single Koopa IR component into assembly code.

use std::vec;

use crate::assembly_builder::{REG_GP, REG_RA, REG_X31};

use super::{
    MyBBValueTable, ARG_SIZE, MAX_SHORT_INT, MIN_SHORT_INT, REGISTER_FOR_ARGS, REGISTER_NAMES,
    REG_A0, REG_SP,
};
use koopa::ir::{entities::ValueData, BinaryOp, FunctionData, Program, TypeKind, Value, ValueKind};

pub trait AssemblyBuildable {
    fn build(&self, program: &Program) -> Result<Vec<String>, String>;
}

impl AssemblyBuildable for Program {
    fn build(&self, _: &Program) -> Result<Vec<String>, String> {
        let mut codes = vec![];
        // Global variables (.data section).
        for (value, value_data) in self.borrow_values().iter() {
            let _ = value;
            codes.extend(value_data.build(self)?);
        }
        // Function definitions (.text section). Declarations (e.g. the SysY
        // library functions) have no basic blocks and are skipped.
        for (_, func_data) in self.funcs() {
            if func_data.layout().entry_bb().is_none() {
                continue;
            }
            codes.extend(func_data.build(self)?);
        }
        Ok(codes)
    }
}

/// Maps a Koopa binary operation and the involved registers to RISC-V
/// assembly. The result is stored in `reg_ans`.
fn binary_op_to_assembly(
    binary: &koopa::ir::values::Binary,
    reg_ans: usize,
    reg1: usize,
    reg2: usize,
) -> String {
    let ans = REGISTER_NAMES[reg_ans];
    let r1 = REGISTER_NAMES[reg1];
    let r2 = REGISTER_NAMES[reg2];
    match binary.op() {
        BinaryOp::Add => format!("  add\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Sub => format!("  sub\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Mul => format!("  mul\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Div => format!("  div\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Mod => format!("  rem\t{}, {}, {}", ans, r1, r2),
        BinaryOp::And => format!("  and\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Or => format!("  or\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Xor => format!("  xor\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Shl => format!("  sll\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Shr => format!("  srl\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Sar => format!("  sra\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Eq => format!("  xor\t{}, {}, {}\n  seqz\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::NotEq => format!("  xor\t{}, {}, {}\n  snez\t{}, {}", ans, r1, r2, ans, ans),
        BinaryOp::Gt => format!("  sgt\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Lt => format!("  slt\t{}, {}, {}", ans, r1, r2),
        BinaryOp::Ge => format!("  slt\t{}, {}, {}\n  xori\t{}, {}, 1", ans, r1, r2, ans, ans),
        BinaryOp::Le => format!("  sgt\t{}, {}, {}\n  xori\t{}, {}, 1", ans, r1, r2, ans, ans),
    }
}

/// Emits `.word` directives (recursively) for a global aggregate initializer.
fn init_global_aggregate(aggr: &koopa::ir::values::Aggregate, program: &Program) -> Vec<String> {
    let mut codes = vec![];
    for elem in aggr.elems() {
        let elem_data = program.borrow_value(*elem);
        match elem_data.kind() {
            ValueKind::Integer(int) => codes.push(format!("  .word {}", int.value())),
            ValueKind::Aggregate(sub_aggr) => {
                codes.extend(init_global_aggregate(sub_aggr, program))
            }
            ValueKind::ZeroInit(_) => {
                codes.push(format!("  .zero {}", elem_data.ty().size()))
            }
            _ => unreachable!("Unexpected value kind in global aggregate initializer!"),
        }
    }
    codes
}

impl AssemblyBuildable for ValueData {
    /// Used to handle global variable declarations.
    /// The ValueData's kind should be GlobalAlloc. Or it will panic.
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let name = self.name().clone().unwrap()[1..].to_string();
        let size = match self.ty().kind() {
            TypeKind::Pointer(base) => base.size(),
            _ => unreachable!("Global variable should be a pointer!"),
        };
        let init = match self.kind() {
            ValueKind::GlobalAlloc(global_alloc) => global_alloc.init(),
            _ => panic!("ValueData::build can only handle GlobalAlloc!"),
        };
        let init_data = program.borrow_value(init);
        let mut codes = vec![
            "  .data".to_string(),
            format!("  .globl {}", name),
            format!("{}:", name),
        ];
        match init_data.kind() {
            ValueKind::Integer(int) => codes.push(format!("  .word {}", int.value())),
            ValueKind::ZeroInit(_) => codes.push(format!("  .zero {}", size)),
            ValueKind::Aggregate(aggr) => codes.extend(init_global_aggregate(aggr, program)),
            _ => unreachable!("Unexpected initializer for global variable!"),
        }
        Ok(codes)
    }
}

/// Adjusts `sp` by `offset` (positive: grow back, negative: allocate).
/// Handles both short (12-bit) and long immediates. Uses `x31` as scratch.
fn adjust_sp(offset: isize) -> Vec<String> {
    if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
        vec![format!("  addi\tsp, sp, {}", offset)]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset.abs()),
            if offset < 0 {
                format!("  sub\tsp, sp, {}", REGISTER_NAMES[REG_X31])
            } else {
                format!("  add\tsp, sp, {}", REGISTER_NAMES[REG_X31])
            },
        ]
    }
}

impl AssemblyBuildable for FunctionData {
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let mut codes = vec![];
        let func_name = self.name()[1..].to_string();

        let mut value_table = MyBBValueTable::new(program, self);

        // ---- First pass: decide the stack frame layout. ----
        // Outgoing arguments (beyond a0-a7) of calls are placed at the
        // bottom of the frame, so compute the space they need first.
        let mut has_call = false;
        let mut max_stack_args = 0usize;
        for (_, node) in self.layout().bbs().iter() {
            for &inst in node.insts().keys() {
                if let ValueKind::Call(call) = self.dfg().value(inst).kind() {
                    has_call = true;
                    if call.args().len() > REGISTER_FOR_ARGS.len() {
                        max_stack_args =
                            max_stack_args.max(call.args().len() - REGISTER_FOR_ARGS.len());
                    }
                }
            }
        }
        let mut offset = max_stack_args * ARG_SIZE;
        // Assign a stack slot for every instruction that occupies memory and
        // for every parameter.
        for (_, node) in self.layout().bbs().iter() {
            for &inst in node.insts().keys() {
                let value_data = self.dfg().value(inst);
                match value_data.kind() {
                    ValueKind::Alloc(_) => {
                        let size = match value_data.ty().kind() {
                            TypeKind::Pointer(base) => base.size(),
                            _ => unreachable!("Alloc should produce a pointer!"),
                        };
                        value_table.local_value_location.insert(inst, offset);
                        offset += size;
                    }
                    _ => {
                        if !value_data.ty().is_unit() {
                            value_table.local_value_location.insert(inst, offset);
                            offset += 4;
                        }
                    }
                }
            }
        }
        for &param in self.params() {
            value_table.local_value_location.insert(param, offset);
            offset += 4;
        }
        // A slot for the return address if this function calls others.
        let ra_offset = match has_call {
            true => {
                let ra_offset = offset;
                offset += 4;
                Some(ra_offset)
            }
            false => None,
        };
        // Align the frame to 16 bytes.
        let frame_size = (offset + 15) / 16 * 16;

        // ---- Prologue. ----
        codes.push("  .text".to_string());
        codes.push(format!("  .globl {}", func_name));
        codes.push(format!("{}:", func_name));
        if frame_size > 0 {
            codes.extend(adjust_sp(-(frame_size as isize)));
        }
        if let Some(ra_offset) = ra_offset {
            codes.extend(value_table.store_with_offset(REG_RA, ra_offset as isize));
        }
        // Move the parameters into their stack slots.
        for (i, &param) in self.params().iter().enumerate() {
            let param_offset = *value_table.local_value_location.get(&param).unwrap();
            if i < REGISTER_FOR_ARGS.len() {
                codes.extend(
                    value_table.store_with_offset(REGISTER_FOR_ARGS[i], param_offset as isize),
                );
            } else {
                // Passed on the stack by the caller: it sits right above our
                // frame. Load it with a scratch register and save it.
                let src_offset = frame_size + (i - REGISTER_FOR_ARGS.len()) * ARG_SIZE;
                codes.extend(value_table.load_with_offset(REG_GP, src_offset as isize));
                codes.extend(value_table.store_with_offset(REG_GP, param_offset as isize));
            }
        }

        // ---- Basic blocks. ----
        for (&bb, node) in self.layout().bbs().iter() {
            let bb_name = self.dfg().bb(bb).name().clone().unwrap()[1..].to_string();
            codes.push(format!("{}:", bb_name));
            for &inst in node.insts().keys() {
                let value_data = self.dfg().value(inst).clone();
                match value_data.kind() {
                    ValueKind::Alloc(_) => {
                        // Space is already reserved in the stack frame.
                    }
                    ValueKind::Store(store) => {
                        let src = store.value();
                        let dest = store.dest();
                        if dest.is_global() {
                            codes.extend(value_table.assign_v1_to_v2(src, dest));
                        } else {
                            match self.dfg().value(dest).kind() {
                                ValueKind::Alloc(_) => {
                                    codes.extend(value_table.assign_v1_to_v2(src, dest));
                                }
                                _ => {
                                    // The destination is a pointer value
                                    // (e.g. from getelemptr/getptr): store
                                    // through the address it holds.
                                    let (reg_src, mut c) =
                                        value_table.want_to_visit_value(src, true, None);
                                    let (_, c2) = value_table.want_to_visit_value(
                                        dest,
                                        true,
                                        Some(REG_X31),
                                    );
                                    c.extend(c2);
                                    c.push(format!(
                                        "  sw\t{}, 0({})",
                                        REGISTER_NAMES[reg_src], REGISTER_NAMES[REG_X31]
                                    ));
                                    codes.extend(c);
                                }
                            }
                        }
                    }
                    ValueKind::Load(load) => {
                        let src = load.src();
                        let src_is_ptr_value = !src.is_global()
                            && !matches!(self.dfg().value(src).kind(), ValueKind::Alloc(_));
                        if src_is_ptr_value {
                            // The source is a pointer value holding an address.
                            let (_, mut c) =
                                value_table.want_to_visit_value(src, true, Some(REG_X31));
                            let (reg_ans, c2) = value_table.get_tmp_reg();
                            c.extend(c2);
                            c.push(format!(
                                "  lw\t{}, 0({})",
                                REGISTER_NAMES[reg_ans], REGISTER_NAMES[REG_X31]
                            ));
                            codes.extend(c);
                            value_table.__update_user(reg_ans, inst);
                        } else {
                            // Load directly from the variable's memory location.
                            let (reg_ans, mut c) = value_table.get_tmp_reg();
                            if src.is_global() {
                                let name = program
                                    .borrow_value(src)
                                    .name()
                                    .clone()
                                    .unwrap()[1..]
                                    .to_string();
                                c.extend(value_table.load_global(reg_ans, name));
                            } else {
                                let src_offset =
                                    *value_table.local_value_location.get(&src).unwrap();
                                c.extend(
                                    value_table.load_with_offset(reg_ans, src_offset as isize)
                                );
                            }
                            codes.extend(c);
                            value_table.__update_user(reg_ans, inst);
                        }
                    }
                    ValueKind::Binary(binary) => {
                        let lhs = binary.lhs();
                        let rhs = binary.rhs();
                        let (mut reg1, mut c) = value_table.want_to_visit_value(lhs, true, None);
                        let (mut reg2, c2) = value_table.want_to_visit_value(rhs, true, None);
                        c.extend(c2);
                        // Loading the second operand may have evicted the
                        // first one from its register. Reload if necessary.
                        if value_table.__is_value_in_register(lhs) != Some(reg1) {
                            let (r, c3) = value_table.want_to_visit_value(lhs, true, None);
                            reg1 = r;
                            c.extend(c3);
                        }
                        if value_table.__is_value_in_register(rhs) != Some(reg2) {
                            let (r, c3) = value_table.want_to_visit_value(rhs, true, None);
                            reg2 = r;
                            c.extend(c3);
                        }
                        let (reg_ans, c4) = value_table.get_tmp_reg();
                        c.extend(c4);
                        c.push(binary_op_to_assembly(binary, reg_ans, reg1, reg2));
                        codes.extend(c);
                        value_table.__update_user(reg_ans, inst);
                    }
                    ValueKind::GetElemPtr(get_elem_ptr) => {
                        codes.extend(build_pointer_arithmetic(
                            &mut value_table,
                            program,
                            self,
                            inst,
                            get_elem_ptr.src(),
                            get_elem_ptr.index(),
                            value_data.ty().clone(),
                        ));
                    }
                    ValueKind::GetPtr(get_ptr) => {
                        codes.extend(build_pointer_arithmetic(
                            &mut value_table,
                            program,
                            self,
                            inst,
                            get_ptr.src(),
                            get_ptr.index(),
                            value_data.ty().clone(),
                        ));
                    }
                    ValueKind::Call(call) => {
                        // Flush every live value to memory before the call:
                        // all the registers we use are caller-saved.
                        codes.extend(value_table.store_global_variables());
                        codes.extend(value_table.store_local_variables());
                        // Arguments beyond a0-a7 go onto the stack.
                        for (i, &arg) in call.args().iter().enumerate() {
                            if i < REGISTER_FOR_ARGS.len() {
                                let (_, c) = value_table.want_to_visit_value(
                                    arg,
                                    true,
                                    Some(REGISTER_FOR_ARGS[i]),
                                );
                                codes.extend(c);
                            } else {
                                let (reg, mut c) =
                                    value_table.want_to_visit_value(arg, true, None);
                                c.extend(value_table.store_with_offset(
                                    reg,
                                    ((i - REGISTER_FOR_ARGS.len()) * ARG_SIZE) as isize,
                                ));
                                codes.extend(c);
                            }
                        }
                        let callee_name =
                            program.func(call.callee()).name()[1..].to_string();
                        codes.push(format!("  call {}", callee_name));
                        // The argument registers are clobbered by the callee.
                        for &reg in REGISTER_FOR_ARGS.iter() {
                            value_table.__free_user(reg);
                        }
                        // Fetch the return value (if any) from a0.
                        if !value_data.ty().is_unit() {
                            let (reg_ans, c) = value_table.get_tmp_reg();
                            codes.extend(c);
                            codes.push(format!(
                                "  mv\t{}, {}",
                                REGISTER_NAMES[reg_ans], REGISTER_NAMES[REG_A0]
                            ));
                            value_table.__update_user(reg_ans, inst);
                        }
                    }
                    ValueKind::Branch(branch) => {
                        let (reg_cond, mut c) =
                            value_table.want_to_visit_value(branch.cond(), true, None);
                        // Block boundary: write everything back to memory.
                        c.extend(value_table.store_global_variables());
                        c.extend(value_table.store_local_variables());
                        let true_bb =
                            self.dfg().bb(branch.true_bb()).name().clone().unwrap()[1..]
                                .to_string();
                        let false_bb =
                            self.dfg().bb(branch.false_bb()).name().clone().unwrap()[1..]
                                .to_string();
                        c.push(format!("  bnez\t{}, {}", REGISTER_NAMES[reg_cond], true_bb));
                        c.push(format!("  j\t{}", false_bb));
                        codes.extend(c);
                    }
                    ValueKind::Jump(jump) => {
                        // Block boundary: write everything back to memory.
                        codes.extend(value_table.store_global_variables());
                        codes.extend(value_table.store_local_variables());
                        let target = self.dfg().bb(jump.target()).name().clone().unwrap()[1..]
                            .to_string();
                        codes.push(format!("  j\t{}", target));
                    }
                    ValueKind::Return(ret) => {
                        if let Some(ret_value) = ret.value() {
                            let (_, c) =
                                value_table.want_to_visit_value(ret_value, true, Some(REG_A0));
                            codes.extend(c);
                        }
                        // Epilogue.
                        if let Some(ra_offset) = ra_offset {
                            codes.extend(value_table.load_with_offset(REG_RA, ra_offset as isize));
                        }
                        if frame_size > 0 {
                            codes.extend(adjust_sp(frame_size as isize));
                        }
                        codes.push("  ret".to_string());
                    }
                    ValueKind::Integer(_)
                    | ValueKind::ZeroInit(_)
                    | ValueKind::Undef(_)
                    | ValueKind::Aggregate(_)
                    | ValueKind::FuncArgRef(_)
                    | ValueKind::BlockArgRef(_)
                    | ValueKind::GlobalAlloc(_) => {
                        // Constants and non-instruction values need no code.
                    }
                }
            }
        }
        Ok(codes)
    }
}

/// Builds the address computation for `getelemptr`/`getptr`:
/// `result = base_address + index * elem_size`.
///
/// Uses `gp` to hold the index and `x31` to hold the base address so that the
/// computation is immune to register eviction in between; the result is put
/// into a fresh temporary register.
fn build_pointer_arithmetic(
    value_table: &mut MyBBValueTable,
    program: &Program,
    fd: &FunctionData,
    inst: Value,
    base: Value,
    index: Value,
    result_ty: koopa::ir::Type,
) -> Vec<String> {
    let elem_size = match result_ty.kind() {
        TypeKind::Pointer(base) => base.size(),
        _ => unreachable!("getelemptr/getptr should produce a pointer!"),
    };
    // 1. The index goes into gp.
    let (reg_index, mut codes) = value_table.want_to_visit_value(index, true, None);
    if reg_index != REG_GP {
        codes.push(format!(
            "  mv\t{}, {}",
            REGISTER_NAMES[REG_GP], REGISTER_NAMES[reg_index]
        ));
    }
    // 2. The base address goes into x31.
    if base.is_global() {
        let name = program.borrow_value(base).name().clone().unwrap()[1..].to_string();
        codes.push(format!("  la\t{}, {}", REGISTER_NAMES[REG_X31], name));
    } else {
        match fd.dfg().value(base).kind() {
            ValueKind::Alloc(_) => {
                let base_offset = *value_table.local_value_location.get(&base).unwrap();
                codes.extend(value_table.add_with_offset(REG_X31, base_offset as isize));
            }
            _ => {
                // The base itself is a pointer value holding an address.
                let (_, c) = value_table.want_to_visit_value(base, true, Some(REG_X31));
                codes.extend(c);
            }
        }
    }
    // 3. result = x31 + gp * elem_size.
    let (reg_ans, c) = value_table.get_tmp_reg();
    codes.extend(c);
    codes.push(format!(
        "  li\t{}, {}",
        REGISTER_NAMES[reg_ans], elem_size
    ));
    codes.push(format!(
        "  mul\t{}, {}, {}",
        REGISTER_NAMES[REG_GP], REGISTER_NAMES[REG_GP], REGISTER_NAMES[reg_ans]
    ));
    codes.push(format!(
        "  add\t{}, {}, {}",
        REGISTER_NAMES[reg_ans], REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_GP]
    ));
    value_table.__update_user(reg_ans, inst);
    codes
}

