// Freestanding SysY runtime for RV32 Linux (qemu-riscv32 linux-user).
// Uses raw ecall syscalls; no libc required.

static inline long syscall3(long n, long a, long b, long c) {
  register long a7 asm("a7") = n;
  register long a0 asm("a0") = a;
  register long a1 asm("a1") = b;
  register long a2 asm("a2") = c;
  asm volatile("ecall" : "+r"(a0) : "r"(a1), "r"(a2), "r"(a7) : "memory");
  return a0;
}

static long sys_read(char *buf, long n) { return syscall3(63, 0, (long)buf, n); }
static long sys_write(const char *buf, long n) { return syscall3(64, 1, (long)buf, n); }
static void sys_exit(int code) { syscall3(93, code, 0, 0); __builtin_unreachable(); }

int main(void);

void _start(void) {
  int ret = main();
  sys_exit(ret);
}

int getch(void) {
  char c;
  if (sys_read(&c, 1) != 1) return -1;
  return (unsigned char)c;
}

int getint(void) {
  int c = getch();
  while (c == ' ' || c == '\n' || c == '\t' || c == '\r') c = getch();
  int sign = 1;
  if (c == '-') { sign = -1; c = getch(); }
  int x = 0;
  while (c >= '0' && c <= '9') {
    x = x * 10 + (c - '0');
    c = getch();
  }
  return x * sign;
}

int getarray(int a[]) {
  int n = getint();
  for (int i = 0; i < n; i++) a[i] = getint();
  return n;
}

void putch(int x) {
  char c = (char)x;
  sys_write(&c, 1);
}

void putint(int x) {
  char buf[16];
  int i = 15;
  buf[i] = '\0';
  unsigned u = x < 0 ? -(unsigned)x : (unsigned)x;
  if (u == 0) buf[--i] = '0';
  while (u) {
    buf[--i] = '0' + u % 10;
    u /= 10;
  }
  if (x < 0) buf[--i] = '-';
  sys_write(&buf[i], 15 - i);
}

void putarray(int n, int a[]) {
  putint(n);
  putch(':');
  for (int i = 0; i < n; i++) {
    putch(' ');
    putint(a[i]);
  }
  putch('\n');
}

void starttime(void) {}
void stoptime(void) {}

